import json
from itertools import permutations

def solve_puzzle():
    houses = [1, 2, 3]

    # Attributes
    names = ["Arnold", "Peter", "Eric"]
    occupations = ["doctor", "teacher", "engineer"]
    educations = ["associate", "high school", "bachelor"]
    smoothies = ["desert", "cherry", "watermelon"]
    hobbies = ["gardening", "cooking", "photography"]

    solutions = []

    for name_perm in permutations(names):
        # 5. The person who loves cooking is Peter. Combined with 4, cooking is in the second house.
        # Therefore, Peter is in the second house.
        if name_perm[1] != "Peter":
            continue

        # 2. Arnold is not in the third house.
        if name_perm[2] == "Arnold":
            continue

        for hobby_perm in permutations(hobbies):
            # 4. The person who loves cooking is in the second house.
            if hobby_perm[1] != "cooking":
                continue

            for occ_perm in permutations(occupations):
                # 8. The person who loves cooking is the person who is a doctor.
                if occ_perm[1] != "doctor":
                    continue

                # 9. The photography enthusiast is the person who is a teacher.
                idx_photo = hobby_perm.index("photography")
                if occ_perm[idx_photo] != "teacher":
                    continue

                for sm_perm in permutations(smoothies):
                    # 1. The Desert smoothie lover is the person who is a doctor.
                    idx_desert = sm_perm.index("desert")
                    if occ_perm[idx_desert] != "doctor":
                        continue

                    # 3. The person who likes Cherry smoothies is somewhere to the right of Peter.
                    idx_peter = name_perm.index("Peter")
                    if sm_perm.index("cherry") <= idx_peter:
                        continue

                    for edu_perm in permutations(educations):
                        # 6. The person with an associate's degree is somewhere to the right of the person who enjoys gardening.
                        if edu_perm.index("associate") <= hobby_perm.index("gardening"):
                            continue

                        # 7. The person with a bachelor's degree is somewhere to the right of the Desert smoothie lover.
                        if edu_perm.index("bachelor") <= idx_desert:
                            continue

                        # All constraints satisfied; build the solution
                        solution_rows = []
                        for i, house in enumerate(houses):
                            row = [
                                str(house),
                                name_perm[i],
                                occ_perm[i],
                                edu_perm[i],
                                sm_perm[i],
                                hobby_perm[i],
                            ]
                            solution_rows.append(row)

                        solutions.append({
                            "header": ["House", "Name", "occupation", "level of education", "favorite smoothie", "hobby"],
                            "rows": solution_rows
                        })

    # Assuming exactly one solution exists; take the first if multiple
    if not solutions:
        raise ValueError("No solution found with the given constraints.")
    return {"solution": solutions[0]}

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, indent=2))
